import{D as e,f as t,u as n}from"./runtime-core.esm-bundler-BeKXeApd.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/education/ms/5550/exam/points.html","title":"Internet & Web Systems","lang":"en-US","frontmatter":{"description":"Network of Networks: The Internet consists of tens of thousands of individual, interconnected networks. Packet Switching: Unlike the telephone network's…","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Internet & Web Systems\\",\\"image\\":[\\"https://davidliuk.github.io/og.jpg\\"],\\"datePublished\\":\\"2026-09-13T00:19:34.000Z\\",\\"dateModified\\":\\"2026-09-13T00:19:34.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"@id\\":\\"https://davidliuk.github.io/#person\\",\\"name\\":\\"David Liu\\",\\"url\\":\\"https://davidliuk.github.io/\\"}],\\"mainEntityOfPage\\":\\"https://davidliuk.github.io/education/ms/5550/exam/points.html\\"}"],["meta",{"property":"og:url","content":"https://davidliuk.github.io/education/ms/5550/exam/points.html"}],["meta",{"property":"og:site_name","content":"David Liu"}],["meta",{"property":"og:title","content":"Internet & Web Systems"}],["meta",{"property":"og:description","content":"Network of Networks: The Internet consists of tens of thousands of individual, interconnected networks. Packet Switching: Unlike the telephone network's…"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://davidliuk.github.io/og.jpg"}],["meta",{"property":"og:locale","content":"en-US"}],["meta",{"property":"og:updated_time","content":"2026-09-13T00:19:34.000Z"}],["meta",{"property":"article:modified_time","content":"2026-09-13T00:19:34.000Z"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:image:type","content":"image/jpeg"}],["meta",{"property":"og:image:alt","content":"Internet & Web Systems"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:image","content":"https://davidliuk.github.io/og.jpg"}],["meta",{"name":"twitter:image:alt","content":"Internet & Web Systems"}],["meta",{"property":"article:published_time","content":"2026-09-13T00:19:34.000Z"}],["link",{"rel":"canonical","href":"https://davidliuk.github.io/education/ms/5550/exam/points.html"}]]},"git":{"createdTime":1789258774000,"updatedTime":1789258774000,"contributors":[{"name":"David Liu","username":"","email":"liu.dawei@bytedance.com","commits":1},{"name":"Claude Opus 5","username":"","email":"noreply@anthropic.com","commits":1}]},"readingTime":{"minutes":20.46,"words":6138},"filePathRelative":"education/ms/5550/exam/points.md","autoDesc":true}`),a={name:`points.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="internet-web-systems" tabindex="-1"><a class="header-anchor" href="#internet-web-systems"><span>Internet &amp; Web Systems</span></a></h1><h2 id="internetbasics" tabindex="-1"><a class="header-anchor" href="#internetbasics"><span>InternetBasics</span></a></h2><h3 id="_1-the-architecture-of-the-internet" tabindex="-1"><a class="header-anchor" href="#_1-the-architecture-of-the-internet"><span>1. The Architecture of the Internet</span></a></h3><ul><li></li></ul><p><strong>Network of Networks:</strong> The Internet consists of tens of thousands of individual, interconnected networks.</p><ul><li><p><strong>Packet Switching:</strong> Unlike the telephone network&#39;s circuit switching, the Internet uses packet switching, where each packet (typically up to ~1,500 bytes) traverses the path independently.</p></li><li><p><strong>IP Protocol (IPv4 vs. IPv6):</strong></p></li><li></li></ul><p><strong>IPv4:</strong> 32-bit addresses (e.g., ), deployed since the 1980s.</p><ul><li></li></ul><p><strong>IPv6:</strong> 128-bit addresses, developed to address the exhaustion of IPv4 addresses and provide technical improvements.</p><ul><li><strong>Non-routable Addresses:</strong> Specific ranges (e.g., , ) are reserved for local use and cannot be announced via BGP. They require <strong>Network Address Translation (NAT)</strong> to connect to remote machines.</li></ul><h3 id="_2-interdomain-routing-and-bgp" tabindex="-1"><a class="header-anchor" href="#_2-interdomain-routing-and-bgp"><span>2. Interdomain Routing and BGP</span></a></h3><ul><li></li></ul><p><strong>Autonomous Systems (AS):</strong> The Internet is divided into ASes, each assigned a unique number by IANA.</p><ul><li></li></ul><p><strong>Border Gateway Protocol (BGP):</strong> The protocol used by border routers to exchange reachability information (prefixes and AS paths).</p><ul><li><strong>Business Relationships:</strong></li><li></li></ul><p><strong>Customer/Provider:</strong> Customers pay providers for transit; providers advertise a route to all active prefixes to the customer.</p><ul><li></li></ul><p><strong>Peering:</strong> Two networks exchange their &quot;customer cones&quot; (their own and their customers&#39; prefixes) for free (settlement-free).</p><ul><li></li></ul><p><strong>Valley-free Routing:</strong> A routing principle where a path first goes &quot;up&quot; (customer to provider), may cross a peering link, and then goes &quot;down&quot; (provider to customer). A path should never go back &quot;up&quot; once it has gone &quot;down&quot;.</p><h3 id="_3-path-properties-and-transport-layer" tabindex="-1"><a class="header-anchor" href="#_3-path-properties-and-transport-layer"><span>3. Path Properties and Transport Layer</span></a></h3><ul><li></li></ul><p><strong>Path Metrics:</strong> * <strong>Bottleneck Capacity:</strong> The limit on how fast data can be sent.</p><ul><li></li></ul><p><strong>Propagation Delay:</strong> The time data takes to travel, limited by the speed of light.</p><ul><li></li></ul><p><strong>Round-Trip Time (RTT):</strong> Total time from sender to receiver and back.</p><ul><li><p><strong>TCP (Transmission Control Protocol):</strong> Provides a reliable byte stream. Key features include retransmission, sequence numbers, flow control, and <strong>Congestion Control</strong> (using Additive Increase, Multiplicative Decrease - AIMD).</p></li><li></li></ul><p><strong>UDP (User Datagram Protocol):</strong> An &quot;unreliable&quot; alternative without retransmissions or congestion control, used by applications that don&#39;t need TCP&#39;s overhead.</p><h3 id="_4-socket-programming" tabindex="-1"><a class="header-anchor" href="#_4-socket-programming"><span>4. Socket Programming</span></a></h3><ul><li></li></ul><p><strong>Socket Abstraction:</strong> An endpoint for communication supported by most OSs.</p><ul><li></li></ul><p><strong>The Five-tuple:</strong> A connection is uniquely identified by (Source IP, Destination IP, Source Port, Destination Port, Protocol).</p><ul><li></li></ul><p><strong>Message Boundaries:</strong> A critical pitfall of stream sockets (TCP) is that they <strong>do not preserve message boundaries</strong>. Applications must define their own boundaries (e.g., using delimiters like CR+LF).</p><hr><h2 id="exam-points-考点模拟" tabindex="-1"><a class="header-anchor" href="#exam-points-考点模拟"><span>Exam Points (考点模拟)</span></a></h2><h3 id="q1-routing-policies" tabindex="-1"><a class="header-anchor" href="#q1-routing-policies"><span>Q1: Routing Policies</span></a></h3><p><strong>Question:</strong> Explain why a BGP route that follows a Provider Customer Provider sequence is considered &quot;invalid&quot; or unlikely in the context of valley-free routing.<br><strong>Answer:</strong> In valley-free routing, a network (the Customer in the middle) would be providing &quot;transit&quot; for its two providers. Since customers typically pay providers for traffic, the middle network would be paying both providers to carry traffic that doesn&#39;t even belong to its own network or its customers. This makes no financial sense.</p><blockquote><p><strong>解析：</strong> 考查对 <strong>Valley-free routing</strong> 经济逻辑的理解。由于流量转发是有成本的，中间的 Customer 不愿意在没有收入的情况下为两个 Provider 提供中转服务。</p></blockquote><h3 id="q2-tcp-congestion-control" tabindex="-1"><a class="header-anchor" href="#q2-tcp-congestion-control"><span>Q2: TCP Congestion Control</span></a></h3><p><strong>Question:</strong> Describe the &quot;Slow Start&quot; phase in TCP congestion control. Is it actually slow?<br><strong>Answer:</strong> In the Slow Start phase, the congestion window () increases exponentially. For every incoming ACK, the is increased by one packet. Despite the name, it is &quot;actually fast&quot; because the sending rate doubles every RTT until it hits a threshold () or a packet drop occurs.</p><blockquote><p><strong>解析：</strong> 考查 <strong>Slow Start</strong> 的机制。重点在于它是“指数增长”而非线性增长，虽然名字叫 Slow，但其实是抓紧时间探测带宽的最快方式。</p></blockquote><h3 id="q3-socket-programming-pitfalls" tabindex="-1"><a class="header-anchor" href="#q3-socket-programming-pitfalls"><span>Q3: Socket Programming Pitfalls</span></a></h3><p><strong>Question:</strong> A developer calls <code>write()</code> twice to send two separate strings, &quot;Hello&quot; and &quot;World&quot;, over a TCP socket. Why might the receiver see &quot;HelloWorld&quot; in a single <code>read()</code> call?</p><p><strong>Answer:</strong> TCP provides a <strong>reliable stream of bytes</strong> but does <strong>not preserve message boundaries</strong>. The OS/network may buffer or segment data differently than the application-level calls. The receiver might get both strings in one chunk, or one string split across multiple chunks.</p><blockquote><p><strong>解析：</strong> 考查 <strong>TCP Stream</strong> 的本质。TCP 像水管里的水，不保证发送端的一“杯”水到接收端还是一“杯”，可能连成一片。解决方法是应用层加分隔符或长度前缀 。</p></blockquote><h3 id="q4-bgp-security" tabindex="-1"><a class="header-anchor" href="#q4-bgp-security"><span>Q4: BGP Security</span></a></h3><p><strong>Question:</strong> What is a &quot;BGP Hijack,&quot; and how can a misconfiguration like the 2004 TTNet incident cause it?</p><p><strong>Answer:</strong> A BGP Hijack occurs when an AS erroneously (or maliciously) announces a path to a prefix it does not own or have a valid route to. In 2004, TTNet announced over 100,000 prefixes, causing a massive amount of global Internet traffic to be re-routed through Turkey because other routers believed TTNet had the best path to those addresses.</p><blockquote><p><strong>解析：</strong> 考查 <strong>BGP Security</strong>。重点在于 BGP 默认是互相信任的，任何 AS 都可以宣告任何前缀，导致流量被错误引导。</p></blockquote><hr><p>希望这份复习指南能帮你顺利通过考试！如果你需要我详细讲解某个特定的 Java Socket 代码示例或 BGP 关系图，随时告诉我。<strong>Would you like me to create a mock quiz based on the &quot;Interdomain Routing&quot; section to test your knowledge further?</strong></p><h2 id="the-web" tabindex="-1"><a class="header-anchor" href="#the-web"><span>The Web</span></a></h2><h3 id="_1-web-fundamentals-and-architecture" tabindex="-1"><a class="header-anchor" href="#_1-web-fundamentals-and-architecture"><span>1. Web Fundamentals and Architecture</span></a></h3><ul><li></li></ul><p><strong>The Web vs. The Internet:</strong> The Web is a service that runs on top of the Internet; they are not identical.</p><p>+1</p><ul><li><p><strong>Architecture Models:</strong></p><ul><li></li></ul><p><strong>Peer-to-Peer:</strong> All machines are equal; any machine can store and request documents.</p><p>+1</p><ul><li></li></ul><p><strong>Client-Server:</strong> Centralized model where servers offer services and clients request them. Most real-world services (Web, Email) use this model.</p><p>+2</p></li><li><p><strong>Naming Schemes (URI, URN, URL):</strong></p><ul><li></li></ul><p><strong>URI (Uniform Resource Identifier):</strong> General term for identifiers.</p><ul><li></li></ul><p><strong>URN (Uniform Resource Name):</strong> Specifies <em>what</em> to find, independent of location (e.g., ISBN).</p><ul><li></li></ul><p><strong>URL (Uniform Resource Locator):</strong> Specifies <em>where</em> to find something.</p></li></ul><h3 id="_2-http-1-1-protocol-basics" tabindex="-1"><a class="header-anchor" href="#_2-http-1-1-protocol-basics"><span>2. HTTP/1.1: Protocol Basics</span></a></h3><ul><li></li></ul><p><strong>Request/Response Structure:</strong> Contains a start line, optional headers (ASCII separated by CR+LF), and an optional body.</p><p>+1</p><ul><li></li></ul><p><strong>Common Methods:</strong> * <strong>GET:</strong> Retrieve information.</p><ul><li></li></ul><pre><code>**POST:** Add new information/dynamic content.

+1
</code></pre><ul><li></li></ul><pre><code>**HEAD:** Retrieve only metadata.
</code></pre><ul><li></li></ul><p><strong>Status Codes:</strong> Important ones include <strong>200 OK</strong>, <strong>301 Moved Permanently</strong>, <strong>403 Forbidden</strong>, <strong>404 Not Found</strong>, and <strong>500 Internal Server Error</strong>.</p><p>+2</p><ul><li><p><strong>Headers:</strong> <code>Connection: keep-alive</code> allows persistent connections; <code>Content-Type</code> uses MIME types (e.g., <code>text/html</code>, <code>image/png</code>) to identify data nature.</p><p>+3</p></li></ul><h3 id="_3-html-and-css" tabindex="-1"><a class="header-anchor" href="#_3-html-and-css"><span>3. HTML and CSS</span></a></h3><ul><li></li></ul><p><strong>Core Idea:</strong> Separate <strong>representation</strong> (structure/semantic content) from <strong>presentation</strong> (visual layout).</p><p>+2</p><ul><li></li></ul><p><strong>Structure:</strong> Hierarchical elements defined by tags and attributes (e.g., <code>&lt;img&gt;</code> has <code>src</code> and <code>alt</code>).</p><ul><li></li></ul><p><strong>CSS:</strong> Formatting instructions are kept in separate files and linked to HTML to reduce redundancy and improve readability.</p><p>+1</p><h3 id="_4-evolution-http-2-and-http-3" tabindex="-1"><a class="header-anchor" href="#_4-evolution-http-2-and-http-3"><span>4. Evolution: HTTP/2 and HTTP/3</span></a></h3><ul><li></li></ul><p><strong>HTTP/1.1 Challenges:</strong> High Page Load Time (PLT) due to <strong>Head-of-Line (HOL) blocking</strong>, no prioritization, and lack of server push.</p><p>+4</p><ul><li></li></ul><p><strong>HTTP/2 Features:</strong> * <strong>Binary Framing Layer:</strong> Replaces plain text with binary frames.</p><p>+2</p><ul><li></li></ul><pre><code>**Multiplexing:** Multiple streams over a single TCP connection.

+1
</code></pre><ul><li></li></ul><pre><code>**Header Compression (HPACK):** Verbose headers are compressed using static/dynamic lists and Huffman coding.

+1
</code></pre><ul><li></li></ul><pre><code>**Server Push:** Server can send resources (e.g., CSS) before the client asks for them.

+2
</code></pre><ul><li></li></ul><p><strong>HTTP/3 (QUIC):</strong> Replaces TCP with <strong>QUIC (on top of UDP)</strong> to solve HOL blocking at the transport layer, as packet loss in one TCP stream no longer stalls others.</p><p>+2</p><hr><h2 id="exam-points-考点模拟-1" tabindex="-1"><a class="header-anchor" href="#exam-points-考点模拟-1"><span>Exam Points (考点模拟)</span></a></h2><h3 id="q1-http-methods-get-vs-post" tabindex="-1"><a class="header-anchor" href="#q1-http-methods-get-vs-post"><span>Q1: HTTP Methods - GET vs. POST</span></a></h3><p><strong>Question:</strong> Compare the GET and POST methods in terms of idempotency and data handling.</p><p><strong>Answer:</strong> <strong>GET</strong> should be used for <strong>idempotent</strong> requests—those safe to re-execute without side effects (like a search). Data is appended to the URL, which has length restrictions and supports only text. <strong>POST</strong> is used for non-idempotent actions; it works with arbitrary data (including binaries) sent in the request body.</p><p>+2</p><blockquote><p><strong>解析：</strong> 考查对 HTTP 方法设计哲学的理解。重点在于 <strong>Idempotent（幂等性）</strong>，面试和考试常考。GET 将数据暴露在 URL 中且有限制，POST 更适合提交大量或敏感数据。</p></blockquote><h3 id="q2-head-of-line-hol-blocking" tabindex="-1"><a class="header-anchor" href="#q2-head-of-line-hol-blocking"><span>Q2: Head-of-Line (HOL) Blocking</span></a></h3><p><strong>Question:</strong> Explain how HOL blocking is addressed differently in HTTP/2 versus HTTP/3.</p><p><strong>Answer:</strong> In <strong>HTTP/2</strong>, HOL blocking is partially addressed at the application layer through a binary framing layer that allows multiplexing multiple streams over one TCP connection. However, TCP still sees a single sequence of bytes; if a packet is lost, all streams are delayed. <strong>HTTP/3</strong> solves this by replacing TCP with <strong>QUIC</strong>, making streams independent so loss in one does not affect others.</p><p>+4</p><blockquote><p><strong>解析：</strong> 考查协议演进的核心动力。要区分“应用层”和“传输层”的 HOL。HTTP/2 解决了并发请求的排队，但没解决 TCP 自身的丢包阻塞；HTTP/3 通过 QUIC 彻底解决了这个问题。</p></blockquote><h3 id="q3-server-push-in-http-2" tabindex="-1"><a class="header-anchor" href="#q3-server-push-in-http-2"><span>Q3: Server Push in HTTP/2</span></a></h3><p><strong>Question:</strong> How does an HTTP/2 server inform a client about a pushed resource, and how can the client respond?</p><p><strong>Answer:</strong> The server sends a <strong>PUSH_PROMISE</strong> frame to tell the client which resource is coming. If the client already has the resource (e.g., in cache), it can decline the push by sending an <strong>RST_STREAM</strong> frame.</p><p>+1</p><blockquote><p><strong>解析：</strong> 考查 HTTP/2 <strong>Server Push</strong> 的具体信令机制。重点是 <code>PUSH_PROMISE</code>（承诺）和 <code>RST_STREAM</code>（拒绝），这体现了协议的主动性和客户端的控制权。</p></blockquote><h2 id="scalability" tabindex="-1"><a class="header-anchor" href="#scalability"><span>Scalability</span></a></h2><h3 id="_1-defining-scale-and-scalability" tabindex="-1"><a class="header-anchor" href="#_1-defining-scale-and-scalability"><span>1. Defining Scale and Scalability</span></a></h3><ul><li><strong>Scale:</strong> Refers to the volume of requests, the amount of data stored, or the number of concurrent users a system handles.</li><li><strong>Scalability:</strong> The ability of a system to handle a growing amount of work by adding resources to the system.</li><li><strong>Performance vs. Scalability:</strong> Performance is about how fast a single request is handled; scalability is about how many total requests can be handled.</li></ul><h3 id="_2-scaling-strategies" tabindex="-1"><a class="header-anchor" href="#_2-scaling-strategies"><span>2. Scaling Strategies</span></a></h3><ul><li><strong>Vertical Scaling (Scaling Up):</strong> Increasing the capacity of a single machine (e.g., adding more RAM, faster CPU).</li><li><strong>Horizontal Scaling (Scaling Out):</strong> Adding more machines to the pool of resources (e.g., a cluster of commodity servers).</li><li><strong>The &quot;Shared-Nothing&quot; Architecture:</strong> A common approach in horizontal scaling where each node is independent and self-sufficient.</li></ul><h3 id="_3-load-balancing" tabindex="-1"><a class="header-anchor" href="#_3-load-balancing"><span>3. Load Balancing</span></a></h3><ul><li><strong>Load Balancer:</strong> A device or software that distributes incoming network traffic across a group of backend servers.</li><li><strong>Distribution Strategies:</strong><ul><li><strong>Round Robin:</strong> Sequential distribution.</li><li><strong>Least Connections:</strong> Sends traffic to the server with the fewest active sessions.</li><li><strong>IP Hashing:</strong> Uses a hash of the client&#39;s IP to ensure the same user always hits the same server (session persistence).</li></ul></li></ul><h3 id="_4-caching-and-state-management" tabindex="-1"><a class="header-anchor" href="#_4-caching-and-state-management"><span>4. Caching and State Management</span></a></h3><ul><li><strong>Caching:</strong> Storing results of expensive computations or frequent data lookups in high-speed storage.</li><li><strong>Cache Invalidation:</strong> The challenge of ensuring the cache remains consistent with the database.</li><li><strong>Statelessness:</strong> To scale horizontally, servers should ideally be &quot;stateless,&quot; meaning any server can handle any request because session data is stored externally (e.g., in a shared DB or via cookies).</li></ul><h3 id="_5-concurrency-models-threads-vs-events" tabindex="-1"><a class="header-anchor" href="#_5-concurrency-models-threads-vs-events"><span>5. Concurrency Models: Threads vs. Events</span></a></h3><ul><li><strong>Multi-threaded (Thread-per-request):</strong> A new thread is assigned to each incoming request. This is easier to program but has high overhead due to context switching and memory usage.</li><li><strong>Event-driven (Asynchronous):</strong> A single thread (or small pool) handles events and callbacks. It is highly efficient for I/O-bound tasks but harder to implement for CPU-bound tasks.</li></ul><h3 id="_6-database-scalability-and-cap-theorem" tabindex="-1"><a class="header-anchor" href="#_6-database-scalability-and-cap-theorem"><span>6. Database Scalability and CAP Theorem</span></a></h3><ul><li><strong>Database Sharding:</strong> Partitioning a database into smaller, faster, more easily managed parts called shards.</li><li><strong>CAP Theorem:</strong> States that a distributed data store can only provide two of the following three guarantees: <ol><li><strong>Consistency:</strong> Every read receives the most recent write.</li><li><strong>Availability:</strong> Every request receives a response.</li><li><strong>Partition Tolerance:</strong> The system continues to operate despite an arbitrary number of messages being dropped or delayed by the network.</li></ol></li></ul><hr><h2 id="exam-points-考点模拟-2" tabindex="-1"><a class="header-anchor" href="#exam-points-考点模拟-2"><span>Exam Points (考点模拟)</span></a></h2><h3 id="q1-vertical-vs-horizontal-scaling" tabindex="-1"><a class="header-anchor" href="#q1-vertical-vs-horizontal-scaling"><span>Q1: Vertical vs. Horizontal Scaling</span></a></h3><p><strong>Question:</strong> Discuss the primary disadvantages of Vertical Scaling compared to Horizontal Scaling for a hyper-scale application like TikTok.</p><p><strong>Answer:</strong> Vertical scaling has an absolute &quot;ceiling&quot; (hardware limits); once you buy the fastest CPU available, you cannot scale further. It also introduces a Single Point of Failure (SPOF) and often requires downtime to upgrade hardware. Horizontal scaling allows for near-infinite growth using cheap, commodity hardware and provides better fault tolerance.</p><blockquote><p><strong>解析：</strong> 考查两种扩展方式的优劣。对于 David 你以后要去的 TikTok 这种量级的公司，纵向扩展（加钱买更贵的机器）很快就会触及物理天花板，而横向扩展（加更多的机器）才是王道。</p></blockquote><h3 id="q2-load-balancing-and-session-persistence" tabindex="-1"><a class="header-anchor" href="#q2-load-balancing-and-session-persistence"><span>Q2: Load Balancing and Session Persistence</span></a></h3><p><strong>Question:</strong> If a web application requires users to stay logged in, why might a simple &quot;Round Robin&quot; load balancing strategy cause issues? Suggest a solution.</p><p><strong>Answer:</strong> Round Robin may send subsequent requests from the same user to different backend servers. If session state is stored locally on the server, the user will be logged out. Solutions include using <strong>Sticky Sessions (IP Hashing)</strong> to route the user to the same server, or move the session state to a <strong>centralized store</strong> like Redis.</p><blockquote><p><strong>解析：</strong> 考查 <strong>负载均衡</strong> 与 <strong>Session 状态</strong> 的冲突。这是开发分布式系统时最经典的坑。</p></blockquote><h3 id="q3-cap-theorem-trade-offs" tabindex="-1"><a class="header-anchor" href="#q3-cap-theorem-trade-offs"><span>Q3: CAP Theorem Trade-offs</span></a></h3><p><strong>Question:</strong> In the event of a network partition (P), a distributed system must choose between Consistency (C) and Availability (A). Explain the consequence of choosing Availability.</p><p><strong>Answer:</strong> Choosing Availability (AP) means the system will always return a response, even if it cannot guarantee that the data is the most recent due to the partition. This may result in different users seeing different data (temporary inconsistency).</p><blockquote><p><strong>解析：</strong> 考查 <strong>CAP 定理</strong>。在网络分区（P）发生时，如果要保证可用性（A），就得允许不同节点的数据暂时不同步（牺牲 C）。</p></blockquote><h3 id="q4-concurrency-models" tabindex="-1"><a class="header-anchor" href="#q4-concurrency-models"><span>Q4: Concurrency Models</span></a></h3><p><strong>Question:</strong> Why is an event-driven model (like Node.js or Nginx) generally considered more scalable than a traditional thread-per-request model?</p><p><strong>Answer:</strong> Threads are expensive in terms of memory (stack space) and CPU (context switching). An event-driven model uses a single thread to manage thousands of concurrent connections by using non-blocking I/O, thus avoiding the overhead associated with managing a massive number of threads.</p><blockquote><p><strong>解析：</strong> 考查 <strong>并发模型</strong>。线程很重，事件循环（Event Loop）很轻。这也是为什么像 Nginx 这种事件驱动的服务器能扛住超高并发的原因。</p></blockquote><h2 id="dynamic-content" tabindex="-1"><a class="header-anchor" href="#dynamic-content"><span>Dynamic Content</span></a></h2><h3 id="_1-static-vs-dynamic-content" tabindex="-1"><a class="header-anchor" href="#_1-static-vs-dynamic-content"><span>1. Static vs. Dynamic Content</span></a></h3><ul><li><strong>Static Content</strong>: The server simply returns a file from its disk. It is efficient and easy to cache, but content remains the same for all users and requests.</li><li><strong>Dynamic Content</strong>: The server runs a program to generate the document on-the-fly. This allows customization based on user identity, time, or input (e.g., search results).</li><li><strong>Server-side vs. Client-side</strong>: Server-side scripts (e.g., Java, PHP) run on the web server. Client-side scripts (JavaScript) run in the user&#39;s browser.</li></ul><h3 id="_2-common-gateway-interface-cgi" tabindex="-1"><a class="header-anchor" href="#_2-common-gateway-interface-cgi"><span>2. Common Gateway Interface (CGI)</span></a></h3><ul><li><strong>Standardization</strong>: CGI was the first standard for connecting web servers to external programs.</li><li><strong>Execution Model</strong>: For every incoming request, the server &quot;forks&quot; and creates a <strong>new process</strong> to run the CGI script.</li><li><strong>Input/Output</strong>: Request headers are passed via <strong>environment variables</strong>; the response is sent back to the server via <strong>stdout</strong>.</li><li><strong>Scalability Bottleneck</strong>: Creating a new process for every request is very expensive in terms of CPU and memory, making CGI unsuitable for high-traffic sites.</li></ul><h3 id="_3-beyond-cgi-optimization-techniques" tabindex="-1"><a class="header-anchor" href="#_3-beyond-cgi-optimization-techniques"><span>3. Beyond CGI: Optimization Techniques</span></a></h3><ul><li><strong>FastCGI</strong>: Replaces the one-process-per-request model with a pool of persistent processes that handle multiple requests, reducing startup overhead.</li><li><strong>Server Modules</strong>: Integrates the script interpreter directly into the web server process (e.g., <code>mod_php</code> for Apache), avoiding the need for inter-process communication.</li><li><strong>Java Servlets</strong>: Uses a <strong>multi-threaded</strong> approach within a single Java Virtual Machine (JVM). Servlets are classes loaded once and then re-used for many requests.</li></ul><h3 id="_4-java-servlet-lifecycle" tabindex="-1"><a class="header-anchor" href="#_4-java-servlet-lifecycle"><span>4. Java Servlet Lifecycle</span></a></h3><ul><li><strong>init()</strong>: Called once when the servlet is first loaded into memory.</li><li><strong>service()</strong>: Called for every request (typically dispatched to <code>doGet()</code> or <code>doPost()</code>).</li><li><strong>destroy()</strong>: Called once when the server decides to unload the servlet (e.g., during shutdown).</li></ul><h3 id="_5-state-management-and-sessions" tabindex="-1"><a class="header-anchor" href="#_5-state-management-and-sessions"><span>5. State Management and Sessions</span></a></h3><ul><li><strong>Stateless HTTP</strong>: By design, HTTP does not &quot;remember&quot; previous requests.</li><li><strong>Solution 1: Cookies</strong>: Small pieces of data stored on the client side and sent back to the server with every subsequent request.</li><li><strong>Solution 2: URL Rewriting</strong>: Appending a unique ID to every link (e.g., <code>;jsessionid=123</code>).</li><li><strong>Solution 3: Hidden Form Fields</strong>: Storing state in <code>&lt;input type=&quot;hidden&quot;&gt;</code> within HTML forms.</li></ul><h3 id="_6-client-side-dynamics-javascript-and-ajax" tabindex="-1"><a class="header-anchor" href="#_6-client-side-dynamics-javascript-and-ajax"><span>6. Client-side Dynamics: JavaScript and AJAX</span></a></h3><ul><li><strong>DOM (Document Object Model)</strong>: A tree-like representation of the page that JavaScript can manipulate to change content without a reload.</li><li><strong>AJAX (Asynchronous JavaScript and XML)</strong>: Allows the browser to send requests to the server in the background and update parts of the page dynamically.</li></ul><hr><h2 id="exam-points-考点模拟-3" tabindex="-1"><a class="header-anchor" href="#exam-points-考点模拟-3"><span>Exam Points (考点模拟)</span></a></h2><h3 id="q1-cgi-vs-servlets-performance" tabindex="-1"><a class="header-anchor" href="#q1-cgi-vs-servlets-performance"><span>Q1: CGI vs. Servlets Performance</span></a></h3><p><strong>Question</strong>: Explain why Java Servlets generally offer better performance and scalability than traditional CGI scripts.</p><p><strong>Answer</strong>: Traditional CGI scripts require the web server to create a new <strong>process</strong> for every incoming request, which involves significant overhead (forking, memory allocation, script initialization). In contrast, Java Servlets use a <strong>multi-threaded</strong> model where a single persistent JVM process handles requests in lightweight threads. This avoids the cost of process creation and allows shared resources (like database connections) to be cached across requests.</p><blockquote><p><strong>解析</strong>：考查对<strong>并发模型</strong>和<strong>开销</strong>的理解。重点在于进程（Process）与线程（Thread）的区别：进程创建成本极高，而线程共享资源且创建极快。</p></blockquote><h3 id="q2-servlet-lifecycle-and-persistence" tabindex="-1"><a class="header-anchor" href="#q2-servlet-lifecycle-and-persistence"><span>Q2: Servlet Lifecycle and Persistence</span></a></h3><p><strong>Question</strong>: If you want to initialize a database connection pool that is shared by all requests to a servlet, in which lifecycle method should you put the connection code? Why?</p><p><strong>Answer</strong>: The database connection code should be placed in the <code>init()</code> method. This is because <code>init()</code> is called only once when the servlet is loaded, ensuring that the pool is created once and reused by all subsequent calls to the <code>service()</code> method. Putting it in <code>service()</code> would recreate the pool for every request, which is inefficient.</p><blockquote><p><strong>解析</strong>：考查对 <strong>Servlet 生命周期</strong> 的掌握。<code>init()</code> 用于一次性初始化，<code>service()</code> 用于处理每次请求。</p></blockquote><h3 id="q3-session-tracking-alternatives" tabindex="-1"><a class="header-anchor" href="#q3-session-tracking-alternatives"><span>Q3: Session Tracking Alternatives</span></a></h3><p><strong>Question</strong>: A user has disabled cookies in their browser. What are two alternative methods a developer can use to maintain the user&#39;s session state?</p><p><strong>Answer</strong>:</p><ol><li><strong>URL Rewriting</strong>: The server can append a session identifier to all links and redirect URLs (e.g., <code>example.com/page?id=XYZ</code>).</li><li><strong>Hidden Form Fields</strong>: State information can be embedded in HTML forms as hidden inputs and submitted via POST requests.</li></ol><blockquote><p><strong>解析</strong>：考查 <strong>状态管理</strong>。因为 HTTP 是无状态的，必须通过某种方式将 ID 传回服务器。Cookie 是首选，但如果被禁用，则需退而求其次使用 URL 重写或隐藏域。</p></blockquote><h3 id="q4-ajax-benefits" tabindex="-1"><a class="header-anchor" href="#q4-ajax-benefits"><span>Q4: AJAX Benefits</span></a></h3><p><strong>Question</strong>: How does AJAX improve the user experience compared to the traditional request-response model?</p><p><strong>Answer</strong>: In the traditional model, any update requires the browser to reload the entire page, causing a &quot;flicker&quot; and consuming bandwidth for redundant data. AJAX allows the browser to request only the specific data needed and update a portion of the page via the DOM, resulting in a smoother, faster, and more &quot;app-like&quot; experience.</p><blockquote><p><strong>解析</strong>：考查 <strong>AJAX</strong> 的核心价值。重点是“异步请求”和“局部更新”，避免了整页刷新。</p></blockquote><h2 id="the-client-side" tabindex="-1"><a class="header-anchor" href="#the-client-side"><span>The Client Side</span></a></h2><h3 id="_1-javascript-and-client-side-scripting" tabindex="-1"><a class="header-anchor" href="#_1-javascript-and-client-side-scripting"><span>1. JavaScript and Client-side Scripting</span></a></h3><ul><li><strong>Purpose:</strong> To make web pages interactive and dynamic without requiring a full page reload from the server.</li><li><strong>Standardization:</strong> JavaScript is standardized as <strong>ECMAScript</strong> (e.g., ES6) to ensure consistent behavior across different browsers.</li><li><strong>Execution:</strong> JavaScript is an interpreted, high-level language that runs in the browser&#39;s sandbox environment for security.</li></ul><h3 id="_2-the-document-object-model-dom" tabindex="-1"><a class="header-anchor" href="#_2-the-document-object-model-dom"><span>2. The Document Object Model (DOM)</span></a></h3><ul><li><strong>Definition:</strong> An API for HTML and XML documents that represents the page as a <strong>tree of nodes</strong>.</li><li><strong>Hierarchy:</strong> The root is the <code>document</code> object; elements, attributes, and text are all nodes in the tree.</li><li><strong>Operations:</strong> * <strong>Access:</strong> <code>getElementById()</code>, <code>querySelector()</code>. <ul><li><strong>Modification:</strong> Changing <code>innerHTML</code>, updating CSS styles via <code>.style</code>, or adding/removing nodes.</li></ul></li></ul><h3 id="_3-event-driven-programming" tabindex="-1"><a class="header-anchor" href="#_3-event-driven-programming"><span>3. Event-driven Programming</span></a></h3><ul><li><strong>Mechanism:</strong> Browsers generate <strong>events</strong> (e.g., <code>click</code>, <code>submit</code>, <code>load</code>) in response to user actions or system changes.</li><li><strong>Listeners:</strong> Scripts use event listeners (<code>addEventListener</code>) to execute code (callback functions) when a specific event occurs.</li></ul><h3 id="_4-asynchronous-communication-ajax-fetch" tabindex="-1"><a class="header-anchor" href="#_4-asynchronous-communication-ajax-fetch"><span>4. Asynchronous Communication (AJAX &amp; Fetch)</span></a></h3><ul><li><strong>AJAX (Asynchronous JavaScript and XML):</strong> A technique to send and receive data from a server asynchronously in the background.</li><li><strong>Core Objects:</strong> Originally used <code>XMLHttpRequest</code> (XHR); modern applications use the more powerful and Promise-based <strong>Fetch API</strong>.</li><li><strong>JSON (JavaScript Object Notation):</strong> A lightweight data interchange format that has largely replaced XML for web communication due to its ease of parsing in JavaScript.</li></ul><h3 id="_5-client-side-security" tabindex="-1"><a class="header-anchor" href="#_5-client-side-security"><span>5. Client-side Security</span></a></h3><ul><li><strong>Same-Origin Policy (SOP):</strong> A fundamental security measure that permits scripts on one page to access data on another page only if both pages have the same <strong>Origin</strong> (Protocol + Host + Port).</li><li><strong>Vulnerabilities:</strong><ul><li><strong>Cross-Site Scripting (XSS):</strong> Injecting malicious scripts into a trusted website; these scripts then run in the victim&#39;s browser.</li><li><strong>Cross-Site Request Forgery (CSRF):</strong> Tricking a logged-in user into performing an unwanted action on a different website where they are authenticated.</li></ul></li><li><strong>Defense:</strong> Using <strong>Content Security Policy (CSP)</strong> to restrict which resources (scripts, styles) a browser is allowed to load for a given page.</li></ul><hr><h2 id="exam-points-考点模拟-4" tabindex="-1"><a class="header-anchor" href="#exam-points-考点模拟-4"><span>Exam Points (考点模拟)</span></a></h2><h3 id="q1-same-origin-policy-sop-logic" tabindex="-1"><a class="header-anchor" href="#q1-same-origin-policy-sop-logic"><span>Q1: Same-Origin Policy (SOP) Logic</span></a></h3><p><strong>Question:</strong> A script running on <code>https://penn.edu:443</code> wants to access data from <code>http://penn.edu:443</code>. Will the browser allow this? Why?</p><p><strong>Answer:</strong> No, the browser will block this. Although the host and port are the same, the <strong>Protocol</strong> is different (<code>https</code> vs <code>http</code>). The Same-Origin Policy requires all three components (Protocol, Host, and Port) to match exactly.</p><blockquote><p><strong>解析：</strong> 考查对 <strong>SOP（同源策略）</strong> 定义的精确掌握。记住“三位一体”：协议、域名、端口，缺一不可。</p></blockquote><h3 id="q2-xss-vs-csrf" tabindex="-1"><a class="header-anchor" href="#q2-xss-vs-csrf"><span>Q2: XSS vs. CSRF</span></a></h3><p><strong>Question:</strong> Distinguish between XSS and CSRF in terms of where the malicious code resides and what is being exploited.</p><p><strong>Answer:</strong> In <strong>XSS</strong>, the attacker injects a malicious script directly <strong>into a trusted website&#39;s database or HTML</strong>, exploiting the user&#39;s trust in that site. In <strong>CSRF</strong>, the attacker hosts a malicious script <strong>on their own site</strong> and exploits the site&#39;s trust in the user&#39;s browser (specifically, the user&#39;s active session/cookies) to force an action.</p><blockquote><p><strong>解析：</strong> 考查 <strong>Web 安全</strong>。简单记法：XSS 是脚本进了别人的家（注入代码）；CSRF 是冒充别人的手（利用 Cookie 发伪造请求）。</p></blockquote><h3 id="q3-dom-tree-manipulation" tabindex="-1"><a class="header-anchor" href="#q3-dom-tree-manipulation"><span>Q3: DOM Tree Manipulation</span></a></h3><p><strong>Question:</strong> Explain the performance implications of frequent direct DOM manipulations.</p><p><strong>Answer:</strong> Direct DOM manipulation is expensive because it often triggers the browser to <strong>re-calculate the layout (reflow)</strong> and <strong>re-paint</strong> the screen. To optimize performance, developers often use techniques like batching updates or using a &quot;Virtual DOM&quot; (as seen in frameworks like React) to minimize actual changes to the real DOM tree.</p><blockquote><p><strong>解析：</strong> 考查 <strong>DOM 性能瓶颈</strong>。DOM 操作慢是因为它触及了浏览器的渲染引擎。这是为什么现代框架（React, Vue）存在的理论基础，面试时非常爱考。</p></blockquote><h3 id="q4-asynchronous-data-handling" tabindex="-1"><a class="header-anchor" href="#q4-asynchronous-data-handling"><span>Q4: Asynchronous Data Handling</span></a></h3><p><strong>Question:</strong> Why is the Fetch API generally preferred over <code>XMLHttpRequest</code> in modern JavaScript development?</p><p><strong>Answer:</strong> <code>Fetch</code> provides a cleaner, more readable syntax and returns <strong>Promises</strong>, making it easier to handle asynchronous flows and avoid &quot;callback hell&quot; compared to the event-based callback model of <code>XMLHttpRequest</code>.</p><blockquote><p><strong>解析：</strong> 考查 <strong>AJAX 进化史</strong>。Promise 是 ES6 之后的灵魂，解决了异步嵌套过深的问题。</p></blockquote><h2 id="naming-systems" tabindex="-1"><a class="header-anchor" href="#naming-systems"><span>Naming Systems</span></a></h2><h3 id="_1-names-vs-addresses" tabindex="-1"><a class="header-anchor" href="#_1-names-vs-addresses"><span>1. Names vs. Addresses</span></a></h3><ul><li><strong>Address:</strong> Specifies <em>where</em> a resource is (e.g., an IP address like <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>158.130.69.163</mn></mrow><annotation encoding="application/x-tex">158.130.69.163</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">158.130.69.163</span></span></span></span>).</li><li><strong>Name:</strong> Specifies <em>what</em> a resource is (e.g., <code>www.upenn.edu</code>). Names are easier for humans to remember and allow resources to move to different addresses without changing their identity.</li><li><strong>The Naming Problem:</strong> We need a system to map these human-readable names to machine-routable addresses efficiently and at scale.</li></ul><h3 id="_2-the-domain-name-system-dns" tabindex="-1"><a class="header-anchor" href="#_2-the-domain-name-system-dns"><span>2. The Domain Name System (DNS)</span></a></h3><ul><li><strong>Architecture:</strong> A distributed, hierarchical database.</li><li><strong>Hierarchy:</strong><ul><li><strong>Root Servers:</strong> The top of the tree (13 logical addresses, hundreds of physical servers via Anycast).</li><li><strong>Top-Level Domains (TLD):</strong> Handle <code>.com</code>, <code>.org</code>, <code>.edu</code>, etc..</li><li><strong>Authoritative Servers:</strong> Managed by organizations (e.g., UPenn&#39;s own servers for <code>upenn.edu</code>).</li></ul></li></ul><h3 id="_3-dns-resolution-process" tabindex="-1"><a class="header-anchor" href="#_3-dns-resolution-process"><span>3. DNS Resolution Process</span></a></h3><ul><li><strong>Recursive Resolution:</strong> The client asks a local resolver (e.g., provided by an ISP or Google 8.8.8.8), and that resolver does all the work to find the answer.</li><li><strong>Iterative Resolution:</strong> The resolver asks the Root, which points to the TLD, which points to the Authoritative server. The resolver &quot;iterates&quot; through the steps until it finds the IP.</li></ul><h3 id="_4-resource-records-rr" tabindex="-1"><a class="header-anchor" href="#_4-resource-records-rr"><span>4. Resource Records (RR)</span></a></h3><p>DNS stores records in a specific format: <code>(Name, Value, Type, TTL)</code>.</p><ul><li><strong>Type A:</strong> Name is a hostname, Value is an <strong>IPv4</strong> address.</li><li><strong>Type AAAA:</strong> Name is a hostname, Value is an <strong>IPv6</strong> address.</li><li><strong>Type CNAME:</strong> Name is an alias, Value is the <strong>canonical name</strong> (real name) of the host.</li><li><strong>Type NS:</strong> Value is the hostname of the <strong>authoritative name server</strong> for the domain.</li><li><strong>Type MX:</strong> Value is the name of the <strong>mail server</strong> for the domain.</li></ul><h3 id="_5-scalability-security-and-privacy" tabindex="-1"><a class="header-anchor" href="#_5-scalability-security-and-privacy"><span>5. Scalability, Security, and Privacy</span></a></h3><ul><li><strong>Caching &amp; TTL:</strong> Resolvers cache answers to reduce load. The <strong>Time-to-Live (TTL)</strong> determines how long a record stays in the cache before it must be refreshed.</li><li><strong>Anycast:</strong> Multiple physical servers share the same IP address. BGP routing automatically sends requests to the &quot;closest&quot; server, improving latency and resilience.</li><li><strong>Security (DNSSEC):</strong> Adds digital signatures to DNS records to prevent spoofing/poisoning.</li><li><strong>Privacy (DoH/DoT):</strong> Encrypts DNS queries using HTTPS or TLS to prevent eavesdropping by ISPs or attackers.</li></ul><hr><h2 id="exam-points-考点模拟-5" tabindex="-1"><a class="header-anchor" href="#exam-points-考点模拟-5"><span>Exam Points (考点模拟)</span></a></h2><h3 id="q1-iterative-vs-recursive-queries" tabindex="-1"><a class="header-anchor" href="#q1-iterative-vs-recursive-queries"><span>Q1: Iterative vs. Recursive Queries</span></a></h3><p><strong>Question:</strong> In a standard DNS resolution, why do Root and TLD servers typically only support iterative queries rather than recursive ones?</p><p><strong>Answer:</strong> Root and TLD servers sit at the top of the global hierarchy and handle an immense volume of traffic. Supporting recursive queries would require them to maintain state for millions of pending requests and perform their own outbound lookups, which would quickly exhaust their resources and make them vulnerable to DDoS attacks. By only supporting iterative queries, they simply provide a &quot;pointer&quot; to the next step and remain highly available.</p><blockquote><p><strong>解析：</strong> 考查对 <strong>Scalability (可扩展性)</strong> 的理解。根服务器和 TLD 是互联网的基石，必须保持极致的简洁和高效。如果让它们去做递归查询，它们会被全世界的请求“拖垮”。</p></blockquote><h3 id="q2-cname-vs-a-records" tabindex="-1"><a class="header-anchor" href="#q2-cname-vs-a-records"><span>Q2: CNAME vs. A Records</span></a></h3><p><strong>Question:</strong> A company moves its website from a local server to a Content Delivery Network (CDN). Should they use an A record or a CNAME record to point <code>www.company.com</code> to the CDN? Explain the advantage.</p><p><strong>Answer:</strong> They should use a <strong>CNAME</strong> record. By pointing <code>www.company.com</code> to a canonical name provided by the CDN (e.g., <code>customer.cdn.com</code>), the company allows the CDN to manage the actual IP addresses. The CDN can then return different IP addresses based on the user&#39;s location or server load without the company ever needing to update its own DNS settings.</p><blockquote><p><strong>解析：</strong> 考查 <strong>Indirection (间接层)</strong> 的应用。CNAME 允许通过别名进行跳转，这对于 CDN 这种需要动态调整背后实际 IP 的服务至关重要。</p></blockquote><h3 id="q3-dns-cache-poisoning" tabindex="-1"><a class="header-anchor" href="#q3-dns-cache-poisoning"><span>Q3: DNS Cache Poisoning</span></a></h3><p><strong>Question:</strong> Briefly explain the &quot;Kaminsky Attack&quot; and how it exploits the lack of security in basic DNS.</p><p><strong>Answer:</strong> The Kaminsky attack exploits the fact that DNS traditionally relies on a 16-bit Transaction ID to match requests with responses. An attacker sends a flood of forged responses with different IDs for a non-existent subdomain (e.g., <code>123.google.com</code>). This forces the resolver to ask the authoritative server repeatedly, giving the attacker many &quot;guesses&quot; to correctly spoof a response that &quot;poisons&quot; the cache with a malicious IP for the main domain (<code>google.com</code>).</p><blockquote><p><strong>解析：</strong> 考查 <strong>DNS Security</strong>。由于原始 DNS 协议设计时没考虑安全性，仅靠一个很短的 ID 来验证响应。Kaminsky 攻击通过大量尝试，“撞”对那个 ID，从而把错误的 IP 塞进缓存。</p></blockquote><h3 id="q4-anycast-routing" tabindex="-1"><a class="header-anchor" href="#q4-anycast-routing"><span>Q4: Anycast Routing</span></a></h3><p><strong>Question:</strong> How does Anycast help protect DNS Root servers from DDoS attacks?</p><p><strong>Answer:</strong> Anycast allows the same IP address to be announced from multiple geographic locations via BGP. During a DDoS attack, the malicious traffic is naturally &quot;diluted&quot; because it is routed to the physically closest Anycast node. This prevents the entire service from being overwhelmed, as an attack in one region (e.g., Europe) won&#39;t necessarily affect nodes in another (e.g., North America).</p><blockquote><p><strong>解析：</strong> 考查 <strong>Anycast</strong> 的分布式特性。这是大厂（如 Google, Cloudflare）应对流量攻击的神技，让流量在地理上分散，避免单点过载。</p></blockquote><p>Python</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>import pypdf</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def extract_pdf_content(file_path):</span></span>
<span class="line"><span>    pdf_text = &quot;&quot;</span></span>
<span class="line"><span>    with open(file_path, &#39;rb&#39;) as file:</span></span>
<span class="line"><span>        reader = pypdf.PdfReader(file)</span></span>
<span class="line"><span>        for page_num, page in enumerate(reader.pages):</span></span>
<span class="line"><span>            pdf_text += f&quot;--- PAGE {page_num + 1} ---\\n&quot;</span></span>
<span class="line"><span>            pdf_text += page.extract_text() + &quot;\\n&quot;</span></span>
<span class="line"><span>    return pdf_text</span></span>
<span class="line"><span></span></span>
<span class="line"><span>content = extract_pdf_content(&quot;uploaded file 08-TheCloud.pdf&quot;)</span></span>
<span class="line"><span>print(content[:5000]) # Print first 5000 chars to check structure</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Code output</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>Traceback (most recent call last):</span></span>
<span class="line"><span>  File &quot;&lt;string&gt;&quot;, line 12, in &lt;module&gt;</span></span>
<span class="line"><span>  File &quot;&lt;string&gt;&quot;, line 5, in extract_pdf_content</span></span>
<span class="line"><span>FileNotFoundError: [Errno 2] No such file or directory: &#39;uploaded file 08-TheCloud.pdf&#39;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Python</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>import os</span></span>
<span class="line"><span>print(os.listdir(&#39;.&#39;))</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>Code output</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-"><span class="line"><span>[]</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>你好，David！这一章 <strong>The Cloud（云计算）</strong> 是分布式系统的集大成者，也是现代互联网架构的物质基础。虽然这一章概念性较强，但在系统设计和性能优化中至关重要。</p><p>以下是针对《The Cloud》讲义的核心知识总结与考点解析。</p><hr><h2 id="the-cloud" tabindex="-1"><a class="header-anchor" href="#the-cloud"><span>The Cloud</span></a></h2><h3 id="_1-definition-and-nist-characteristics" tabindex="-1"><a class="header-anchor" href="#_1-definition-and-nist-characteristics"><span>1. Definition and NIST Characteristics</span></a></h3><p>云计算不仅仅是“别人的电脑”，它必须具备 NIST 定义的五个核心特征：</p><ul><li><strong>On-demand self-service</strong>: Users can provision resources (CPU, storage) automatically without human interaction with the provider.</li><li><strong>Broad network access</strong>: Services are available over the network and accessed through standard mechanisms (mobile, laptop).</li><li><strong>Resource pooling</strong>: The provider’s computing resources are pooled to serve multiple consumers (Multi-tenancy).</li><li><strong>Rapid elasticity</strong>: Capabilities can be elastically provisioned and released to scale rapidly outward and inward with demand.</li><li><strong>Measured service</strong>: Resource usage is monitored and billed based on a pay-per-use (utility) model.</li></ul><h3 id="_2-cloud-service-models-the-stack" tabindex="-1"><a class="header-anchor" href="#_2-cloud-service-models-the-stack"><span>2. Cloud Service Models (The &quot;Stack&quot;)</span></a></h3><p>云计算通常分为三层服务模型，每一层向用户屏蔽的细节程度不同：</p><ul><li><strong>IaaS (Infrastructure as a Service)</strong>: Provides raw resources (Virtual Machines, storage, networks). Users manage the OS and everything above it. <em>Example: Amazon EC2, Google Compute Engine.</em></li><li><strong>PaaS (Platform as a Service)</strong>: Provides a platform for developers to deploy applications without managing the OS. <em>Example: Google App Engine, Heroku.</em></li><li><strong>SaaS (Software as a Service)</strong>: Provides a complete software application over the web. Users only manage their data and settings. <em>Example: Gmail, Salesforce.</em></li></ul><h3 id="_3-virtualization-the-engine-of-the-cloud" tabindex="-1"><a class="header-anchor" href="#_3-virtualization-the-engine-of-the-cloud"><span>3. Virtualization: The Engine of the Cloud</span></a></h3><ul><li><strong>Hypervisors</strong>: The software layer that allows multiple virtual machines (VMs) to run on a single physical host. <ul><li><strong>Type 1 (Bare-metal)</strong>: Runs directly on hardware (e.g., Xen, VMware ESXi).</li><li><strong>Type 2 (Hosted)</strong>: Runs on a host OS (e.g., VirtualBox).</li></ul></li><li><strong>VMs vs. Containers</strong>: <ul><li><strong>VMs</strong>: Include a full guest OS; offer strong isolation but are heavy and slow to boot.</li><li><strong>Containers (e.g., Docker)</strong>: Share the host OS kernel; are lightweight, fast, and ideal for microservices.</li></ul></li></ul><h3 id="_4-cloud-economics-serverless" tabindex="-1"><a class="header-anchor" href="#_4-cloud-economics-serverless"><span>4. Cloud Economics &amp; Serverless</span></a></h3><ul><li><strong>CapEx to OpEx</strong>: Moving from Capital Expenditure (buying hardware) to Operational Expenditure (paying for usage).</li><li><strong>Serverless Computing (FaaS)</strong>: The cloud provider manages the server completely. Developers only write functions (e.g., AWS Lambda) that execute in response to events. Scalability is automatic and handled by the provider.</li></ul><hr><h2 id="exam-points-考点模拟-6" tabindex="-1"><a class="header-anchor" href="#exam-points-考点模拟-6"><span>Exam Points (考点模拟)</span></a></h2><h3 id="q1-service-model-classification" tabindex="-1"><a class="header-anchor" href="#q1-service-model-classification"><span>Q1: Service Model Classification</span></a></h3><p><strong>Question</strong>: A startup wants to host a custom-built Java application. They don&#39;t want to worry about patching the Operating System or managing hardware, but they need to control the version of the Java Runtime Environment (JRE). Which service model is most appropriate?</p><p><strong>Answer</strong>: <strong>PaaS (Platform as a Service)</strong>. PaaS is designed for developers who want to focus on application deployment while the provider handles the OS and underlying infrastructure.</p><blockquote><p><strong>解析</strong>：考查对 <strong>Service Models</strong> 适用场景的理解。重点在于“控制权”与“管理负担”的权衡。用户不想要管理 OS（排除 IaaS），但需要部署应用（排除 SaaS），因此 PaaS 是最佳选择。</p></blockquote><h3 id="q2-elasticity-vs-scalability" tabindex="-1"><a class="header-anchor" href="#q2-elasticity-vs-scalability"><span>Q2: Elasticity vs. Scalability</span></a></h3><p><strong>Question</strong>: Explain the subtle difference between &quot;Scalability&quot; and &quot;Rapid Elasticity&quot; in a cloud context.</p><p><strong>Answer</strong>: <strong>Scalability</strong> is the <em>capability</em> of a system to handle increased load by adding resources. <strong>Rapid Elasticity</strong> is the <em>automatic and dynamic</em> nature of this scaling—the ability to grow or shrink resources in real-time to match current demand perfectly without manual intervention.</p><blockquote><p><strong>解析</strong>：考查 <strong>云计算核心特性</strong>。Scalability 是“能变大”，Elasticity 是“能随着需求自动变大变小”。云计算的精髓在于后者，它能避免在需求低谷时浪费资源（节省成本）。</p></blockquote><h3 id="q3-virtualization-overhead" tabindex="-1"><a class="header-anchor" href="#q3-virtualization-overhead"><span>Q3: Virtualization Overhead</span></a></h3><p><strong>Question</strong>: Why do containers generally have lower performance overhead compared to Virtual Machines (VMs)?</p><p><strong>Answer</strong>: Containers share the <strong>host Operating System&#39;s kernel</strong>, whereas each VM runs its own full <strong>guest Operating System</strong>. This means containers avoid the memory and CPU overhead of running multiple kernel instances and the hardware emulation required by traditional VMs.</p><blockquote><p><strong>解析</strong>：考查 <strong>Virtualization</strong> 的底层原理。共享内核（Shared Kernel）是容器（Docker）之所以轻量且高效的根本原因。</p></blockquote><h3 id="q4-serverless-trade-offs" tabindex="-1"><a class="header-anchor" href="#q4-serverless-trade-offs"><span>Q4: Serverless Trade-offs</span></a></h3><p><strong>Question</strong>: What is one major disadvantage of Serverless (FaaS) computing compared to VM-based hosting for a high-traffic, steady-state application?</p><p><strong>Answer</strong>: <strong>Cost efficiency at scale and &quot;Cold Start&quot; issues</strong>. For steady-state workloads, a dedicated VM is often cheaper than paying per-invocation for FaaS. Additionally, FaaS functions may experience latency on the first call after a period of inactivity (Cold Start).</p><blockquote><p><strong>解析</strong>：考查 <strong>Serverless (FaaS)</strong> 的优缺点。Serverless 适合突发性（Bursty）流量；对于持续稳定的高流量，购买预留实例（Reserved Instances）通常更划算。</p></blockquote>`,279)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};